root.command:

IF OBJECT_ID(N'dbo.MobileApiSettingsTbl', N'U') IS NOT NULL
   AND NOT EXISTS (
       SELECT 1
       FROM sys.extended_properties ep
       WHERE ep.major_id = OBJECT_ID(N'dbo.MobileApiSettingsTbl')
         AND ep.minor_id = 0
         AND ep.name = N'RunDoneOnDeliveryOn_v1')
BEGIN
    IF EXISTS (SELECT 1 FROM dbo.MobileApiSettingsTbl WHERE SettingsID = 1)
        UPDATE dbo.MobileApiSettingsTbl
        SET RunDoneOnDelivery = 1, UpdatedAt = GETDATE(), UpdatedBy = N'3.0.3.3 update'
        WHERE SettingsID = 1;
    ELSE
        INSERT INTO dbo.MobileApiSettingsTbl (SettingsID, RunDoneOnDelivery, UpdatedBy)
        VALUES (1, 1, N'3.0.3.3 update');

    EXEC sys.sp_addextendedproperty
        @name = N'RunDoneOnDeliveryOn_v1',
        @value = N'1',
        @level0type = N'SCHEMA', @level0name = N'dbo',
        @level1type = N'TABLE',  @level1name = N'MobileApiSettingsTbl';
END
